//! R036/08: Project-wide source search with atomic bounded matches. Real guest filesystem/workstation operation.
use super::Error;
use crate::batch7_ramfs::{RamFs,CONTENT_MAX,PATH_MAX};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub struct Match{pub path:[u8;PATH_MAX],pub len:usize,pub offset:usize,pub revision:u64}pub const EMPTY:Match=Match{path:[0;PATH_MAX],len:0,offset:0,revision:0};pub fn search<const F:usize,const N:usize>(fs:&RamFs<F>,root:&[u8],needle:&[u8],out:&mut[Match;N])->Result<usize,Error>{if needle.is_empty()||root.len()<2{return Err(Error::Invalid);}let mut stage=[EMPTY;N];let mut count=0;for i in 0..fs.count(){let mut path=[0;PATH_MAX];let(len,bytes,revision)=fs.entry(i,&mut path).map_err(|_|Error::Missing)?.ok_or(Error::Missing)?;if !path[..len].starts_with(root)||path.get(root.len())!=Some(&b'/')||!path[..len].ends_with(b".rs"){continue;}let mut data=[0;CONTENT_MAX];fs.read(&path[..len],0,&mut data[..bytes]).map_err(|_|Error::Missing)?;for (offset,part)in data[..bytes].windows(needle.len()).enumerate(){if part==needle{if count==N{return Err(Error::Full);}stage[count]=Match{path,len,offset,revision};count+=1;}}}*out=stage;Ok(count)}
#[cfg(test)]mod tests{use super::*;#[test]fn real_functional_regression(){let mut fs=RamFs::<2>::new();fs.replace(b"/p/a.rs",b"foo foo").unwrap();fs.replace(b"/p/z.rs",b"foo").unwrap();let mut out=[EMPTY;4];assert_eq!(search(&fs,b"/p",b"foo",&mut out),Ok(3));}}
